@import 'c/ihStyles';

.picker {
    display: flex;
    flex-wrap: wrap;
    border: 1px solid var(--ih-line);
    border-radius: 8px;
    overflow: hidden;
}
.pane {
    flex: 1 1 280px;
    min-width: 0;
    padding: 10px 12px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.pane_list {
    border-right: 1px solid var(--ih-line);
}
.rows {
    list-style: none;
    margin: 0;
    padding: 0;
    max-height: 300px;
    overflow-y: auto;
}
.row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    padding: 5px 8px;
    border: 0;
    border-radius: 6px;
    background: none;
    font: inherit;
    font-size: 13px;
    text-align: left;
    color: var(--ih-ink);
    cursor: pointer;
}
.row:hover,
.row_open {
    background: var(--ih-brand-soft);
}
.row:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: -2px;
}
.row_child {
    padding-left: 26px;
}
.row_on {
    color: var(--ih-brand);
    font-weight: 600;
}
.row-label {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
}
.row-api {
    color: var(--ih-quiet);
    overflow-wrap: anywhere;
    text-align: right;
}
.pad {
    padding: 4px 8px;
}
.add-typed {
    background: none;
    border: 0;
    padding: 4px 8px;
    text-align: left;
    font: inherit;
    font-size: 13px;
}
.chips {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}
.chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 3px 6px 3px 10px;
    border: 1px solid var(--ih-line);
    border-radius: 999px;
    background: #f7f9fb;
    cursor: grab;
    max-width: 100%;
    overflow-wrap: anywhere;
}
.chip:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 1px;
}
.chip_unknown {
    border-color: var(--ih-warn);
    background: var(--ih-warn-bg);
    color: var(--ih-warn-ink);
}
.chip-x {
    border: 0;
    background: none;
    cursor: pointer;
    font-size: 14px;
    line-height: 1;
    padding: 2px 4px;
    color: var(--ih-quiet);
}
.chip-x:hover {
    color: var(--ih-bad);
}

@media (max-width: 640px) {
    .pane_list {
        border-right: 0;
        border-bottom: 1px solid var(--ih-line);
    }
}
